theorem mul_mul_apply_single (M U N : Matrix V V ℂ) {i j k₀ l₀ : V}
    (hk : ∀ k, k ≠ k₀ → M i k = 0) (hl : ∀ l, l ≠ l₀ → N l j = 0) :
